package local.civic.home;
import android.app.Activity;import android.os.Bundle;import android.os.Handler;import android.os.Looper;import android.content.SharedPreferences;import android.graphics.Typeface;import android.graphics.drawable.Drawable;import android.view.Gravity;import android.view.View;import android.view.WindowManager;import android.widget.FrameLayout;import android.widget.LinearLayout;import android.widget.TextView;import java.text.SimpleDateFormat;import java.util.Date;import java.util.Locale;

public final class ScreenSaverActivity extends Activity {
 private TextView clock,date;private LinearLayout box;private SharedPreferences prefs;private long lastMinute=-1;private final Handler h=new Handler(Looper.getMainLooper());
 private SimpleDateFormat clockFormat;private final SimpleDateFormat dateFormat=new SimpleDateFormat("EEE, MMM d",Locale.getDefault());
 private final Runnable tick=new Runnable(){public void run(){Date now=new Date();long minute=now.getTime()/60000;if(minute!=lastMinute){lastMinute=minute;int step=(int)(minute%9);box.setTranslationX(dp((step%3-1)*4));box.setTranslationY(dp((step/3-1)*4));clock.setText(clockFormat.format(now));date.setText(dateFormat.format(now).toUpperCase(Locale.getDefault()));}h.postDelayed(this,60000-System.currentTimeMillis()%60000);}};
 private int dp(int v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}
 @Override public void onCreate(Bundle b){super.onCreate(b);ThemeTokens theme=ThemeTokens.get(this);getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(theme.background));getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);getWindow().getDecorView().setSystemUiVisibility(UiFlags.IMMERSIVE);prefs=getSharedPreferences("home",0);FrameLayout root=new FrameLayout(this);root.setOnClickListener(v->finish());root.setBackground(WallpaperPack.saver(this,theme));if(prefs.getString("saver_mode","clock").equals("image")){setContentView(root);return;}
  box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setGravity(Gravity.CENTER);TextView civic=new TextView(this);String brand=prefs.getString("brand_text","CIVIC");civic.setText(brand.equals("CIVIC")?"C I V I C":brand);civic.setTextColor(0xffadadb0);civic.setTextSize(17);civic.setGravity(Gravity.CENTER);civic.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));civic.setVisibility(prefs.getBoolean("saver_civic",true)&&!brand.isEmpty()?View.VISIBLE:View.GONE);box.addView(civic,new LinearLayout.LayoutParams(-1,dp(30)));
  clock=new TextView(this);clock.setTextColor(theme.textPrimary);int size=prefs.getInt("saver_size",120);clock.setTextSize(size);clock.setTypeface(Typeface.create("sans-serif-condensed-light",Typeface.NORMAL));clock.setGravity(Gravity.CENTER);clock.setIncludeFontPadding(false);box.addView(clock,new LinearLayout.LayoutParams(-1,dp(size+25)));
  date=new TextView(this);date.setTextColor(0xff888b90);date.setTextSize(17);date.setGravity(Gravity.CENTER);date.setLetterSpacing(.12f);date.setVisibility(prefs.getBoolean("saver_date",true)?View.VISIBLE:View.GONE);box.addView(date,new LinearLayout.LayoutParams(-1,dp(34)));root.addView(box,new FrameLayout.LayoutParams(-1,-1));setContentView(root);}
 @Override protected void onResume(){super.onResume();if(box!=null){clockFormat=new SimpleDateFormat(prefs.getBoolean("clock24",false)?"HH:mm":"h:mm",Locale.getDefault());lastMinute=-1;h.removeCallbacks(tick);h.post(tick);}}
 @Override protected void onPause(){h.removeCallbacks(tick);super.onPause();}
 @Override protected void onDestroy(){h.removeCallbacksAndMessages(null);super.onDestroy();}
}
